const w=[{id:"university",label:"University",tagline:"Undergraduate & graduate degrees",levels:["Undergraduate","Graduate"]},{id:"secondary",label:"Secondary School",tagline:"Junior & senior secondary classes",levels:["JSS","SSS"]}],f=e=>w.find(t=>t.id===e),o={math:"https://images.unsplash.com/photo-1509228468518-180dd4864904?auto=format&fit=crop&w=1200&q=80",english:"https://images.unsplash.com/photo-1455390582262-044cdead277a?auto=format&fit=crop&w=1200&q=80",physics:"https://images.unsplash.com/photo-1636466497217-26a8cbeaf0aa?auto=format&fit=crop&w=1200&q=80",chemistry:"https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?auto=format&fit=crop&w=1200&q=80",biology:"https://images.unsplash.com/photo-1530026186672-2cd00ffc50fe?auto=format&fit=crop&w=1200&q=80",computer:"https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1200&q=80",economics:"https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?auto=format&fit=crop&w=1200&q=80",literature:"https://images.unsplash.com/photo-1513475382585-d06e58bcb0e0?auto=format&fit=crop&w=1200&q=80",science:"https://images.unsplash.com/photo-1507413245164-6160d8298b31?auto=format&fit=crop&w=1200&q=80",law:"https://images.unsplash.com/photo-1589829545856-d10d557cf95f?auto=format&fit=crop&w=1200&q=80",data:"https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80",business:"https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1200&q=80",philosophy:"https://images.unsplash.com/photo-1457369804613-52c61a468e7d?auto=format&fit=crop&w=1200&q=80"},g=[{slug:"mathematics-core",title:"Core Mathematics",subject:"Mathematics",branch:"secondary",level:"SSS",teacher:"Mrs. Ngozi Adeyemi",teacherId:"T-201",img:o.math,duration:"8 weeks",lessons:12,blurb:"From foundations to calculus — algebra, geometry, trigonometry and their real-world applications, taught step by step.",outline:["Quadratic equations and functions","Simultaneous equations and matrices","Coordinate geometry and graphs","Trigonometry and its applications"],modules:[{id:"math-m1",title:"Algebra foundations",lessons:[{id:"math-1",title:"Linear equations and inequalities",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We begin by revisiting the balance method for solving linear equations in one variable, then extend the same logic to inequalities. Pay close attention to how multiplying or dividing an inequality by a negative number reverses the direction of the inequality sign."},{id:"math-2",title:"Simultaneous equations",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Linear simultaneous equations are solved by substitution and by elimination. We compare the two methods and identify when each is more efficient, then tackle one real-world problem using these techniques."},{id:"math-3",title:"Quadratic expressions and factorising",minutes:20,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Factorising quadratics takes practice. We review common factors, difference of two squares and trinomials, and connect each technique back to solving equations by the zero-product property."}]},{id:"math-m2",title:"Functions and graphs",lessons:[{id:"math-4",title:"The idea of a function",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"A function is a rule that assigns exactly one output to each input. We define the domain and range, use function notation, and sketch simple relations to see which qualify as functions."},{id:"math-5",title:"Graphing linear functions",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We plot straight-line graphs from equations, read off gradient and intercept, and interpret what the gradient means in applied contexts such as speed and cost per unit."},{id:"math-6",title:"Graphing quadratic functions",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Parabolas: we locate the turning point and roots of a quadratic, sketch the graph of a quadratic function, and use graphs to solve approximate equations."}]},{id:"math-m3",title:"Geometry and trigonometry",lessons:[{id:"math-7",title:"Coordinate geometry",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We compute distances, midpoints and gradients between two points, derive the equation of a straight line, and use these tools for proof."},{id:"math-8",title:"Introduction to trigonometry",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Sine, cosine and tangent are defined from right-angled triangles. We use these ratios to find missing sides and angles, and memorise the exact values for common angles."},{id:"math-9",title:"Applying trigonometry",minutes:19,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"From angles of elevation and depression to navigation problems, trigonometry lets us measure the world without a tape measure. This lesson works through several applied examples."},{id:"math-10",title:"Area and volume",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We consolidate mensuration: areas of compound shapes and the volumes and surface areas of prisms and pyramids, using pi where relevant."}]},{id:"math-m4",title:"Statistics and probability",lessons:[{id:"math-11",title:"Measures of central tendency",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Mean, median and mode each summarise a data set differently. We calculate all three by hand and discuss when each is the most appropriate measure to report."},{id:"math-12",title:"Probability basics",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We define probability as a number between zero and one, use sample spaces and tree diagrams, and combine probabilities for independent events."}]}],quiz:{title:"Core Mathematics — Unit test",questions:[{q:"What is the solution to 2x + 5 = 13?",options:["x = 3","x = 4","x = 5","x = 6"],answer:1},{q:"Factorise x² − 9",options:["(x−3)²","(x−3)(x+3)","(x+9)(x−1)","x(x−9)"],answer:1},{q:"The gradient of the line y = 3x − 2 is…",options:["−2","2","3","−3"],answer:2},{q:"What is sin 30° (exact value)?",options:["1","1/2","√3/2","1/√2"],answer:1},{q:"The median of 3, 5, 7, 9, 11 is…",options:["5","6","7","8"],answer:2}]},assignments:[{id:"math-a1",title:"Algebra problem set",points:20,kind:"Problem set",prompt:"Solve ten quadratics and simultaneous equations, showing full working. Submit a single scanned or photographed document."},{id:"math-a2",title:"Trigonometry application",points:25,kind:"Project",prompt:"Measure a real-world height using a clinometer and report your method, data, calculations and sources of error."}]},{slug:"english-language",title:"English Language & Literature",subject:"English Language",branch:"secondary",level:"SSS",teacher:"Miss Adaku Eze",teacherId:"T-203",img:o.english,duration:"8 weeks",lessons:10,blurb:"Sharpening comprehension, summary, grammar and essay craft, with close reading of poetry and prose.",outline:["Comprehension and summary skills","Grammar and sentence craft","Essay writing and argument","Poetry and prose close reading"],modules:[{id:"eng-m1",title:"Comprehension and summary",lessons:[{id:"eng-1",title:"Active reading strategies",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We learn to read with a pen: highlighting key claims, marking transitions and annotating unfamiliar vocabulary before answering comprehension questions."},{id:"eng-2",title:"Writing a summary",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"A summary keeps only the essential points in your own words. We practise cutting detail, paraphrasing signal phrases and counting words."}]},{id:"eng-m2",title:"Grammar and sentence craft",lessons:[{id:"eng-3",title:"Clauses and sentence types",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Simple, compound and complex sentences each shape tone and rhythm. We identify clauses and experiment with varied sentence structures."},{id:"eng-4",title:"Punctuation for clarity",minutes:11,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Commas, colons, semicolons and dashes — used well they clarify meaning; used badly they mislead. This lesson demystifies the commonest errors."}]},{id:"eng-m3",title:"Essay writing and argument",lessons:[{id:"eng-5",title:"Building an argument",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Every strong essay has a thesis, reasons and evidence. We draft a clear thesis statement and plan a five-paragraph structure."},{id:"eng-6",title:"Introductory and concluding paragraphs",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"The opening hooks the reader and states the thesis; the conclusion leaves a lasting impression. We compare strong and weak examples."},{id:"eng-7",title:"Using textual evidence",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We embed short quotations and paraphrase longer passages, then connect every piece of evidence back to the argument."}]},{id:"eng-m4",title:"Poetry and prose close reading",lessons:[{id:"eng-8",title:"Reading poetry closely",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Sound, imagery, diction and form work together in a poem. We unpick a famous sonnet layer by layer."},{id:"eng-9",title:"Character and narrative voice",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"How do narrators shape our judgement of characters? We analyse point of view, dialogue and description in a short story."},{id:"eng-10",title:"Theme and symbol",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We identify recurring themes and symbols, then trace how they develop through a text to support a reading."}]}],quiz:{title:"English Language — Grammar & style test",questions:[{q:"Which sentence is punctuated correctly?",options:["Its cold today.","It's cold today.","Its’ cold today.","It's a cold day, today."],answer:1},{q:"“Although it rained, the match continued.” is a…",options:["simple sentence","compound sentence","complex sentence","sentence fragment"],answer:2},{q:"A summary should be written…",options:["with copied sentences","in your own words","longer than the original","without a word limit"],answer:1},{q:"The main idea you argue for in an essay is the…",options:["thesis","topic sentence","conclusion","quotation"],answer:0},{q:"Which word is a verb?",options:["happy","jump","slowly","the"],answer:1}]},assignments:[{id:"eng-a1",title:"Persuasive essay",points:30,kind:"Essay",prompt:"Write a 500-word argument on a topic of your choice. Structure it with a thesis, three supporting points and a conclusion, and cite at least two sources."},{id:"eng-a2",title:"Poetry analysis",points:25,kind:"Analysis",prompt:"Choose one poem from the module and write a close reading that examines its imagery, sound and form."}]},{slug:"physics-experiments",title:"Physics: Motion & Mechanics",subject:"Physics",branch:"secondary",level:"SSS",teacher:"Dr. Emeka Nwosu",teacherId:"T-202",img:o.physics,duration:"7 weeks",lessons:11,blurb:"Forces, motion and energy — scalars and vectors, Newton’s laws, work and the conservation of energy.",outline:["Measurement and scalars vs. vectors","Kinematics and motion graphs","Newton’s laws of motion","Work, energy and power"],modules:[{id:"phy-m1",title:"Measuring motion",lessons:[{id:"phy-1",title:"Scalars and vectors",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Distance, speed and time are scalars; displacement, velocity and acceleration carry direction as vectors. We resolve simple vectors and add them."},{id:"phy-2",title:"Speed, velocity and acceleration",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We define average and instantaneous values, convert between m/s and km/h, and solve problems with constant acceleration using the equations of motion."},{id:"phy-3",title:"Motion graphs",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Distance–time and velocity–time graphs tell us a great deal. We read gradients and areas under curves to extract speed, displacement and acceleration."}]},{id:"phy-m2",title:"Forces and Newton’s laws",lessons:[{id:"phy-4",title:"What is a force?",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Forces cause acceleration. We distinguish contact and non-contact forces, draw free-body diagrams, and calculate resultant forces."},{id:"phy-5",title:"Newton’s first and second laws",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"F = ma connects force, mass and acceleration. We apply it to simple systems and discuss the meaning of inertia."},{id:"phy-6",title:"Newton’s third law",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Every action has an equal and opposite reaction. We show why the forces are real but act on different bodies."},{id:"phy-7",title:"Friction and normal force",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Friction opposes motion. We model static and kinetic friction and consider when it is helpful and when it is a nuisance."}]},{id:"phy-m3",title:"Energy and work",lessons:[{id:"phy-8",title:"Work and power",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Work is force times distance; power is the rate of doing work. We compute both and use the correct units (joule and watt)."},{id:"phy-9",title:"Kinetic and potential energy",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Energy exists in many forms. We calculate kinetic energy and gravitational potential energy, and convert between them."},{id:"phy-10",title:"Conservation of energy",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Energy is never created or destroyed, only transferred. We trace energy changes in falling, swinging and moving systems."},{id:"phy-11",title:"Simple machines and efficiency",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Levers, pulleys and inclined planes trade force for distance. We calculate mechanical advantage and efficiency as output over input."}]}],quiz:{title:"Physics — Motion & mechanics test",questions:[{q:"Which of these is a scalar quantity?",options:["Velocity","Displacement","Speed","Acceleration"],answer:2},{q:"F = ma is Newton’s…",options:["first law","second law","third law","law of gravity"],answer:1},{q:"The unit of work is the…",options:["watt","newton","joule","ampere"],answer:2},{q:"A car accelerates from rest at 2 m/s² for 3 s. Its speed is…",options:["2 m/s","3 m/s","6 m/s","9 m/s"],answer:2},{q:"Energy is…",options:["created by machines","destroyed by friction","conserved in transfers","measured in newtons"],answer:2}]},assignments:[{id:"phy-a1",title:"Motion experiment log",points:20,kind:"Lab report",prompt:"Time a rolling trolley down a ramp and record displacement over time. Plot a graph and use it to determine acceleration."},{id:"phy-a2",title:"Energy poster",points:15,kind:"Project",prompt:"Produce a poster tracing the energy transfers of one everyday machine, using the terms from this module."}]},{slug:"biology-foundations",title:"Biology: The Living Cell",subject:"Biology",branch:"secondary",level:"SSS",teacher:"Mrs. Halima Yusuf",teacherId:"T-206",img:o.biology,duration:"6 weeks",lessons:10,blurb:"Cells as the building blocks of life — structure, organisation, transport across membranes and the essentials of inheritance.",outline:["Cell structure and organelles","Cell division and the cell cycle","Transport across membranes","Genetics and inheritance"],modules:[{id:"bio-m1",title:"Inside the cell",lessons:[{id:"bio-1",title:"The cell as the unit of life",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"All living things are made of cells. We compare the light and electron microscope and the scale of the structures they reveal."},{id:"bio-2",title:"Animal and plant cell organelles",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We tour the major organelles — nucleus, mitochondria, ribosomes, chloroplasts — and match each to its job."},{id:"bio-3",title:"Specialised cells and tissues",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Cells specialise to perform distinct roles. We look at red blood cells, muscle cells and root hair cells as examples of adaptation."}]},{id:"bio-m2",title:"Cell activity",lessons:[{id:"bio-4",title:"Diffusion, osmosis and active transport",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Molecules move across membranes in three key ways. We define each process and give biological examples, including the potato in salt water."},{id:"bio-5",title:"The cell cycle and mitosis",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Cells grow and divide. We trace the stages of the cell cycle and mitosis, explaining why chromosomes are copied first."},{id:"bio-6",title:"Enzymes and reactions",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Enzymes are biological catalysts. We explore the lock-and-key model and the effects of temperature and pH on enzyme activity."}]},{id:"bio-m3",title:"Genetics",lessons:[{id:"bio-7",title:"DNA and the genetic code",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"DNA stores the instructions for life. We describe its double-helix structure and how bases pair to carry the genetic code."},{id:"bio-8",title:"Alleles and inheritance",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Using Punnett squares, we predict how traits pass from parents to offspring and distinguish dominant and recessive alleles."},{id:"bio-9",title:"Mutations and variation",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Mutations create new alleles and drive variation. We consider harmless, beneficial and harmful outcomes."},{id:"bio-10",title:"Heredity and disease",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Some conditions are inherited. We use family traits to illustrate patterns and discuss screening and ethics."}]}],quiz:{title:"Biology — The cell test",questions:[{q:"Which organelle is the site of respiration?",options:["Nucleus","Mitochondrion","Chloroplast","Ribosome"],answer:1},{q:"The movement of water across a membrane is called…",options:["diffusion","osmosis","active transport","transpiration"],answer:1},{q:"Mitosis produces cells that are…",options:["genetically different","haploid","identical copies","random"],answer:2},{q:"DNA stores…",options:["energy","genetic information","oxygen","enzymes"],answer:1},{q:"A dominant allele is expressed when…",options:["both alleles are recessive","present at least once","never present","only in males"],answer:1}]},assignments:[{id:"bio-a1",title:"Osmosis in potato strips",points:20,kind:"Lab report",prompt:"Immerse potato strips in solutions of different strengths and record changes in mass. Explain your results using osmosis."},{id:"bio-a2",title:"Cell model",points:15,kind:"Project",prompt:"Build or draw a labelled model of an animal or plant cell and describe the role of each organelle."}]},{slug:"chemistry-basics",title:"Chemistry: Atoms & Reactions",subject:"Chemistry",branch:"secondary",level:"SSS",teacher:"Dr. Emeka Nwosu",teacherId:"T-202",img:o.chemistry,duration:"7 weeks",lessons:10,blurb:"The periodic table, chemical bonding, equations and acids, bases and salts — the language of chemistry.",outline:["Atomic structure and the periodic table","Chemical bonding","Balancing equations","Acids, bases and salts"],modules:[{id:"che-m1",title:"Atoms and the periodic table",lessons:[{id:"che-1",title:"The structure of the atom",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Protons, neutrons and electrons — we locate each particle, give its charge and mass, and define atomic number and mass number."},{id:"che-2",title:"Isotopes and relative atomic mass",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Isotopes are atoms of the same element with different numbers of neutrons. We calculate relative atomic mass from isotopic abundance."},{id:"che-3",title:"The periodic table per period and group",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We read the periodic table: periods, groups and how electron configuration explains both reactivity and the patterns within groups."}]},{id:"che-m2",title:"Bonding and structure",lessons:[{id:"che-4",title:"Ionic bonding",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Metals transfer electrons to non-metals to form ions. We write formulas from charges and describe the lattice that results."},{id:"che-5",title:"Covalent bonding",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Non-metals share electrons. We draw dot-and-cross diagrams for simple molecules and compare their properties with ionic compounds."},{id:"che-6",title:"Metallic bonding",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"A sea of delocalised electrons explains why metals conduct electricity and are malleable. We connect structure to properties."}]},{id:"che-m3",title:"Chemical change",lessons:[{id:"che-7",title:"Chemical equations and balancing",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Equations conserve matter. We practise writing word and symbol equations and balancing them by adjusting coefficients."},{id:"che-8",title:"The mole and quantities",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"The mole is the chemist’s counting unit. We convert between mass, amount in moles and number of particles using molar mass."},{id:"che-9",title:"Acids, bases and neutralisation",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Acids release hydrogen ions and bases release hydroxide ions. We write neutralisation equations and describe the pH scale."},{id:"che-10",title:"Preparing salts",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Salts form when acids react with bases, metals or carbonates. We plan the steps to prepare an insoluble and a soluble salt."}]}],quiz:{title:"Chemistry — Atoms & reactions test",questions:[{q:"The particle with a positive charge is the…",options:["electron","neutron","proton","photon"],answer:2},{q:"Atoms of the same element with different neutron numbers are…",options:["ions","isotopes","molecules","isomers"],answer:1},{q:"Ionic bonding happens when…",options:["electrons are shared","electrons are transferred","protons are shared","energy is released only"],answer:1},{q:"A neutralisation reaction produces a salt and…",options:["oxygen","hydrogen","water","carbon dioxide"],answer:2},{q:"The pH of a neutral solution is…",options:["0","7","14","1"],answer:1}]},assignments:[{id:"che-a1",title:"Balancing equations",points:20,kind:"Problem set",prompt:"Balance ten chemical equations and classify each as combination, decomposition, displacement or neutralisation."},{id:"che-a2",title:"Model an atom",points:15,kind:"Project",prompt:"Construct a labelled 3-D model of an atom of your choice and present the roles of each sub-atomic particle."}]},{slug:"computer-studies",title:"Computer Studies & Programming",subject:"Computer Studies",branch:"secondary",level:"JSS",teacher:"Mr. Tunde Bakare",teacherId:"T-207",img:o.computer,duration:"6 weeks",lessons:10,blurb:"From how computers work to writing your first programs — logic, algorithms, flowcharts and Python.",outline:["How computers work","Hardware and software","Algorithms and flowcharts","Introduction to programming"],modules:[{id:"com-m1",title:"Foundations of computing",lessons:[{id:"com-1",title:"What is a computer?",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We define a computer as a programmable machine that accepts input, processes it and produces output. We follow data through a simple system."},{id:"com-2",title:"Hardware and software",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Hardware is what you can touch; software is the instructions. We tour the CPU, memory, storage and peripheral devices."},{id:"com-3",title:"How data is represented",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Computers store everything as binary. We convert small numbers between decimal and binary and meet bits and bytes."}]},{id:"com-m2",title:"Thinking like a computer",lessons:[{id:"com-4",title:"Algorithms",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"An algorithm is a precise set of steps to solve a problem. We write everyday algorithms and check they handle all cases."},{id:"com-5",title:"Flowcharts",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Flowcharts visualise algorithms with standard symbols for start, process, decision and end. We draw one for a simple program."},{id:"com-6",title:"Logic and sorting",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We explore logical comparisons and step through a simple sorting algorithm to arrange items into order."}]},{id:"com-m3",title:"Get programming",lessons:[{id:"com-7",title:"Your first Python program",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We write and run a first Python program using print, variables and input, in an online editor with no setup."},{id:"com-8",title:"Conditions and loops",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Programs make decisions with if/else and repeat work with loops. We build a small guessing and counting program."},{id:"com-9",title:"Data in programs",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Lists and dictionaries store collections of data. We manipulate a list of student names and scores."},{id:"com-10",title:"Building a mini project",minutes:20,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We combine everything from the module to build a small interactive quiz program, then test and improve it."}]}],quiz:{title:"Computer Studies — Basics test",questions:[{q:"Which is hardware?",options:["A web browser","The keyboard","An operating system","A game"],answer:1},{q:"Computers store data as…",options:["decimal numbers","binary digits","letters","images"],answer:1},{q:"A precise set of steps to solve a problem is an…",options:["algorithm","output","input","error"],answer:0},{q:"Which symbol represents a decision in a flowchart?",options:["rectangle","oval","diamond","arrow"],answer:2},{q:"To repeat a task, a programmer uses a…",options:["loop","variable","print statement","comment"],answer:0}]},assignments:[{id:"com-a1",title:"Flowchart challenge",points:15,kind:"Problem set",prompt:"Draw flowcharts for three everyday tasks, making sure to include at least one decision in each."},{id:"com-a2",title:"Mini quiz program",points:20,kind:"Project",prompt:"Write a short program that asks five questions and keeps score, then test it with a friend."}]},{slug:"economics-principles",title:"Economics: Principles of the Market",subject:"Economics",branch:"secondary",level:"SSS",teacher:"Mrs. Grace Adeleke",teacherId:"T-208",img:o.economics,duration:"6 weeks",lessons:10,blurb:"Scarcity, supply and demand, market structures and the workings of money and national income.",outline:["The basic economic problem","Demand and supply","Market structures","Money and the economy"],modules:[{id:"eco-m1",title:"Scarcity and choice",lessons:[{id:"eco-1",title:"The economic problem",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Wants exceed resources, so every choice has an opportunity cost. We introduce the three basic economic questions."},{id:"eco-2",title:"Factors of production",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Land, labour, capital and enterprise combine to produce goods and services. We identify each factor in examples."},{id:"eco-3",title:"Production possibility curves",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"A production possibility curve shows the trade-offs an economy faces and what it means for an economy to be on or inside the curve."}]},{id:"eco-m2",title:"Markets",lessons:[{id:"eco-4",title:"The law of demand",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Demand falls as price rises. We draw demand curves and distinguish a movement along the curve from a shift of the whole curve."},{id:"eco-5",title:"The law of supply",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Supply rises with price. We sketch supply curves and discuss what moves them, such as technology and input costs."},{id:"eco-6",title:"Market equilibrium",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Buyers and sellers meet at equilibrium where quantity demanded equals quantity supplied. We trace what happens after a shortage or surplus."},{id:"eco-7",title:"Price elasticity",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Elasticity measures how responsive quantity is to price. We compare elastic and inelastic goods and their implications for revenue."}]},{id:"eco-m3",title:"The wider economy",lessons:[{id:"eco-8",title:"Market structures",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"From perfect competition to monopoly, we compare the number of firms, barriers to entry and market power in each structure."},{id:"eco-9",title:"Money and banks",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Money solves the problem of barter. We describe the functions of money and the role of central and commercial banks."},{id:"eco-10",title:"National income",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"GDP measures the size of an economy. We introduce income, expenditure and output approaches and their limits as measures of welfare."}]}],quiz:{title:"Economics — Market principles test",questions:[{q:"The opportunity cost of a choice is…",options:["the price paid","the next best alternative forgone","the money spent","the taxes paid"],answer:1},{q:"As price rises, quantity demanded typically…",options:["rises","falls","stays constant","is unpredictable"],answer:1},{q:"Equilibrium is where…",options:["supply is zero","demand is zero","quantity demanded equals quantity supplied","price is highest"],answer:2},{q:"A market with a single seller is a…",options:["oligopoly","monopoly","duopoly","competitive market"],answer:1},{q:"GDP measures…",options:["unemployment","the size of an economy","inflation only","population"],answer:1}]},assignments:[{id:"eco-a1",title:"Market analysis",points:25,kind:"Analysis",prompt:"Pick a product you buy regularly. Describe its market: likely structure, demand and supply factors, and what happens when price changes."},{id:"eco-a2",title:"Supply and demand diagram",points:15,kind:"Problem set",prompt:"Draw labelled supply and demand curves and show the effect of a relevant shift on equilibrium price and quantity."}]},{slug:"literature-prose",title:"Literature in English: Prose & Drama",subject:"Literature in English",branch:"secondary",level:"SSS",teacher:"Miss Adaku Eze",teacherId:"T-203",img:o.literature,duration:"6 weeks",lessons:9,blurb:"Reading novels and plays with attention to plot, character, setting and theme, and writing about them.",outline:["Understanding plot and structure","Characterisation","Setting and atmosphere","Theme and critical writing"],modules:[{id:"lit-m1",title:"Reading fiction",lessons:[{id:"lit-1",title:"Plot and structure",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We chart the arc of a story — exposition, rising action, climax and resolution — and consider why authors order events as they do."},{id:"lit-2",title:"Narrators and point of view",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"First, second and third person narration each filter the story differently. We examine how point of view shapes trust and sympathy."},{id:"lit-3",title:"Characterisation",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Characters are built through speech, action, description and reaction. We trace how an author reveals a character over time."}]},{id:"lit-m2",title:"Setting and symbolism",lessons:[{id:"lit-4",title:"Setting and atmosphere",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Time and place do far more than supply a backdrop. We read how setting creates mood and reflects themes."},{id:"lit-5",title:"Symbol and motif",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Recurring images carry meaning beyond themselves. We identify symbols and trace a motif through a narrative."},{id:"lit-6",title:"Dialogue and subtext",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"What characters do not say matters as much as what they say. We read dialogue for subtext and conflict."}]},{id:"lit-m3",title:"Writing about literature",lessons:[{id:"lit-7",title:"Formulating an argument",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"A literary essay needs a clear, arguable thesis. We practise turning a question into a strong opening claim."},{id:"lit-8",title:"Using quotations expertly",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Short, well-chosen quotations are woven into sentences. We practise embedding and analysing evidence tightly."},{id:"lit-9",title:"Structuring your essay",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We build paragraphs that open with a point, support it with evidence and explain the analysis, then connect them into an essay."}]}],quiz:{title:"Literature — Reading & interpretation test",questions:[{q:"The sequence of events in a story is its…",options:["setting","plot","theme","character"],answer:1},{q:"A narrator who uses “I” speaks in the…",options:["second person","third person","first person","fourth person"],answer:2},{q:"A recurring object that carries deeper meaning is a…",options:["character","plot","motif/symbol","chapter"],answer:2},{q:"The central idea explored by a text is its…",options:["theme","genre","climax","prologue"],answer:0},{q:"What characters imply but do not say directly is called…",options:["subtext","foreshadowing","dialogue","narrative"],answer:0}]},assignments:[{id:"lit-a1",title:"Close reading essay",points:30,kind:"Essay",prompt:"Choose a short extract from a set text and write a 400–word close reading that explores language, character and theme."},{id:"lit-a2",title:"Character study",points:25,kind:"Analysis",prompt:"Analyse how one character changes over the course of a set novel or play, using specific moments as evidence."}]},{slug:"basic-science",title:"Basic Science: Energy & Life",subject:"Basic Science",branch:"secondary",level:"JSS",teacher:"Mrs. Funmilayo Sanni",teacherId:"T-204",img:o.science,duration:"6 weeks",lessons:9,blurb:"An integrated introduction to energy, living things and the environment for junior secondary students.",outline:["Energy and its forms","Living and non-living things","The environment and sustainability","Scientific investigation"],modules:[{id:"bs-m1",title:"Energy around us",lessons:[{id:"bs-1",title:"Forms of energy",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We meet kinetic, potential, chemical, electrical and light energy, and find examples of each all around us."},{id:"bs-2",title:"Energy transformations",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Energy changes from one form to another. We trace the transformations in a torch, a kettle and a bicycle."},{id:"bs-3",title:"Sound and light",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Sound needs a medium and travels as waves; light travels in straight lines. We compare reflection, refraction and shadows."}]},{id:"bs-m2",title:"Living things",lessons:[{id:"bs-4",title:"Characteristics of living things",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Movement, respiration, growth, reproduction and sensitivity — the signs of life. We sort organisms using these criteria."},{id:"bs-5",title:"Plants and animals",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We compare the basic needs, structures and life processes of green plants and animals, and how energy flows between them."},{id:"bs-6",title:"Food chains and webs",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Producers, consumers and decomposers form food chains and webs. We trace energy through an ecosystem."}]},{id:"bs-m3",title:"Science in action",lessons:[{id:"bs-7",title:"The environment and pollution",minutes:13,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Human activity affects air, water and land. We identify types of pollution and simple ways to reduce our impact."},{id:"bs-8",title:"Doing a fair test",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"A fair test changes one variable at a time. We design a simple experiment, predict and record results."},{id:"bs-9",title:"Science fair project basics",minutes:12,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We plan a simple science project from question to conclusion, and learn how to present findings clearly."}]}],quiz:{title:"Basic Science — Energy & life test",questions:[{q:"Which is a form of energy?",options:["A rock","Kinetic","A tree","Water"],answer:1},{q:"Sound travels through…",options:["a vacuum instantly","a medium such as air","light only","nothing"],answer:1},{q:"A producer in a food chain is usually a…",options:["green plant","herbivore","carnivore","decomposer"],answer:0},{q:"A fair test changes…",options:["everything at once","no variables","one variable at a time","only the equipment"],answer:2},{q:"Reflection is when light…",options:["bends through water","bounces off a surface","is absorbed","changes colour"],answer:1}]},assignments:[{id:"bs-a1",title:"Energy poster",points:15,kind:"Project",prompt:"Make a poster tracing the energy transformations in one household appliance, with arrows and labels."},{id:"bs-a2",title:"Food web diagram",points:15,kind:"Analysis",prompt:"Draw a food web for a local habitat, label the producers and consumers, and predict the effect of removing one species."}]}],b=[{slug:"university-computer-science",title:"Computer Science: Foundations of Programming",subject:"Computer Science",branch:"university",level:"Undergraduate",faculty:"Mathematical, Physical and Life Sciences",code:"FF12",teacher:"Dr. Adebayo Falana",teacherId:"U-101",img:o.computer,duration:"10 weeks",lessons:12,blurb:"From the fundamentals of computation to designing efficient algorithms — programming, data structures and the theory that powers modern software.",outline:["Computational thinking and program design","Data structures and algorithms","Programming paradigms and languages","Software engineering foundations"],modules:[{id:"cs-m1",title:"Foundations of programming",lessons:[{id:"cs-1",title:"Thing and abstraction in computing",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We start with the core idea that computing is the art of abstraction. Variables, expressions and control flow give us our first powerful toolkit."},{id:"cs-2",title:"Working with data types",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Numbers, strings and booleans behave differently under the hood. We compare primitive and composite types and see why types matter at scale."},{id:"cs-3",title:"Functions and modular design",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Functions let us chain small, testable pieces into bigger systems. We discuss scope, parameters and return values and refactor a working program."}]},{id:"cs-m2",title:"Data structures and algorithms",lessons:[{id:"cs-4",title:"Arrays and linked structures",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Sequence is fundamental. We compare contiguous arrays with linked structures and describe the trade-offs in memory and access time."},{id:"cs-5",title:"Stacks, queues and trees",minutes:19,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Abstract data types organise data for specific operations. We meet stacks, queues and binary trees and trace how each supports classic problems."},{id:"cs-6",title:"Searching and sorting",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We compare linear and binary search, and sorting algorithms from bubble sort to mergesort, analysing complexity as input grows."}]},{id:"cs-m3",title:"From algorithms to software",lessons:[{id:"cs-7",title:"Complexity and Big-O",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Big-O notation lets us compare algorithms without a stopwatch. We classify running times and identify bottlenecks in real code."},{id:"cs-8",title:"Programming paradigms",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Imperative, object-oriented, functional and declarative styles each favour different problems. We write a small program in two paradigms to feel the difference."},{id:"cs-9",title:"Testing and debugging",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Bugs are inevitable; discipline is not. We design test cases, use assertions and a debugger, and practise reading stack traces."}]}],quiz:{title:"Computer Science — Programming foundations test",questions:[{q:"Which structure stores items in a first-in, first-out order?",options:["Stack","Queue","Tree","Graph"],answer:1},{q:"Big-O notation describes…",options:["exact run times","growth of resource use","lines of code","memory addresses"],answer:1},{q:"A function in programming is used to…",options:["store data","encapsulate reusable code","compile faster","delete files"],answer:1},{q:"Binary search requires data that is…",options:["random","sorted","circular","encrypted"],answer:1},{q:"Which is a primitive data type?",options:["Integer","Array","Object","Stack"],answer:0}]},assignments:[{id:"cs-a1",title:"Algorithm analysis",points:25,kind:"Problem set",prompt:"Implement three sorting algorithms, measure their running times on random data, and explain the complexity of each."},{id:"cs-a2",title:"Mini software project",points:35,kind:"Project",prompt:"Build a small command-line application that stores and queries records, using the data structures from this course."}]},{slug:"university-business",title:"Business and Management",subject:"Business and Management",branch:"university",level:"Undergraduate",faculty:"Social Sciences",code:"N100",teacher:"Dr. Omowunmi Adekoya",teacherId:"U-102",img:o.business,duration:"9 weeks",lessons:12,blurb:"Organisations, markets people and leadership — the analytical and practical toolkit every manager needs.",outline:["The environment of organisations","Strategic management","Marketing and customers","People and leadership"],modules:[{id:"bes-m1",title:"Organisations and their environment",lessons:[{id:"bes-1",title:"What is an organisation?",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Firms exist to coordinate effort toward shared goals. We compare functional, divisional and matrix structures and when each fits."},{id:"bes-2",title:"The external environment",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Political, economic, social and technological forces shape strategy. We run a PESTEL analysis of a familiar industry."},{id:"bes-3",title:"Stakeholders and CSR",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Shareholders are only one group with a stake. We map stakeholders, their interests and the responsibilities firms carry."}]},{id:"bes-m2",title:"Strategy and marketing",lessons:[{id:"bes-4",title:"Strategic analysis",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"SWOT and Porter’s five forces give structure to messy decisions. We apply them to a company you know well."},{id:"bes-5",title:"Segmentation and positioning",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Markets are not homogeneous. We segment by demographics and behaviour, pick targets and craft a positioning statement."},{id:"bes-6",title:"The marketing mix",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Product, price, place and promotion must work as one system. We design a mix for a new product launch."}]},{id:"bes-m3",title:"People and operations",lessons:[{id:"bes-7",title:"Leadership vs management",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Managers do things right; leaders do the right things. We contrast transactional and transformational styles with real leaders in mind."},{id:"bes-8",title:"Motivation theories",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Maslow, Herzberg and expectancy theory each explain why people work. We translate the theories into practical retention tactics."},{id:"bes-9",title:"Operations and supply chain",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Operations turn inputs into value. We follow a product from order to delivery and identify bottlenecks and quality controls."}]}],quiz:{title:"Business and Management — Essentials test",questions:[{q:"PESTEL analysis examines the…",options:["internal culture","external environment","balance sheet","production line"],answer:1},{q:"The marketing mix includes product, price, place and…",options:["people","promotion","profit","process"],answer:1},{q:"A SWOT analysis covers strengths, weaknesses, opportunities and…",options:["targets","threats","training","taxes"],answer:1},{q:"Managers who are concerned with doing things right are…",options:["leaders","bosses","managers","shareholders"],answer:2},{q:"Dividing a market into distinct groups is called…",options:["positioning","segmentation","pricing","logistics"],answer:1}]},assignments:[{id:"bes-a1",title:"Industry analysis",points:30,kind:"Analysis",prompt:"Choose an industry and deliver a PESTEL plus five-forces analysis, concluding with the strategic implications for a leading firm."},{id:"bes-a2",title:"Marketing plan",points:30,kind:"Plan",prompt:"Prepare a one-page marketing plan for a product or service: target segment, positioning and a coherent marketing mix."}]},{slug:"university-economics",title:"Economics: Markets, Money and Growth",subject:"Economics",branch:"university",level:"Undergraduate",faculty:"Social Sciences",code:"L100",teacher:"Prof. Adewale Ogunlana",teacherId:"U-103",img:o.economics,duration:"10 weeks",lessons:12,blurb:"Choice, markets and the macroeconomy — microeconomic behaviour, macroeconomic policy and the data behind both.",outline:["Microeconomic foundations","Market structure and welfare","Macroeconomics and policy","Economic data and evidence"],modules:[{id:"econ-m1",title:"Microeconomic foundations",lessons:[{id:"econ-1",title:"Scarcity and opportunity cost",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Every choice has a cost. We build the production possibility frontier and use it to show scarcity, trade-offs and growth."},{id:"econ-2",title:"Demand, supply and markets",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Markets coordinate buyers and sellers. We model shifts of and movements along demand and supply curves and find equilibrium."},{id:"econ-3",title:"Elasticity in practice",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Elasticity tells us who really bears a tax and how revenue changes with price. We compute price elasticities and interpret them."}]},{id:"econ-m2",title:"Market structure and welfare",lessons:[{id:"econ-4",title:"Consumer and producer behaviour",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We maximise utility and profit formally: budget lines, indifference curves and the marginal conditions that follow."},{id:"econ-5",title:"Competition and monopoly",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Perfect competition delivers efficient outcomes; monopoly restricts quantity and creates deadweight loss. We compare them side by side."},{id:"econ-6",title:"Market failure and the state",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Externalities, public goods and information gaps pull markets away from efficiency. We discuss taxes, subsidies and regulation as remedies."}]},{id:"econ-m3",title:"The macroeconomy",lessons:[{id:"econ-7",title:"Measuring the economy",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"GDP, inflation and unemployment are headline numbers that need careful reading. We define each and its measurement problems."},{id:"econ-8",title:"Money and interest rates",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Central banks set the price of money. We trace the transmission from policy rates to credit, spending and prices."},{id:"econ-9",title:"Fiscal and monetary policy",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Governments and central banks manage the cycle. We compare discretionary policy, automatic stabilisers and the limits of each."}]}],quiz:{title:"Economics — Principles test",questions:[{q:"The opportunity cost of a choice is…",options:["the money spent","the next best alternative forgone","the total benefit","the tax paid"],answer:1},{q:"A monopoly sets prices…",options:["equal to cost","above marginal cost","below average cost","at zero"],answer:1},{q:"GDP measures…",options:["unemployment","total output","inflation","population"],answer:1},{q:"A market failure caused by pollution is a…",options:["public good","negative externality","natural monopoly","moral hazard"],answer:1},{q:"Central banks mainly target…",options:["exchange rates only","interest rates","tax collection","immigration"],answer:1}]},assignments:[{id:"econ-a1",title:"Microeconomic case study",points:30,kind:"Analysis",prompt:"Take a real market, model its demand and supply, identify any market failure and evaluate the policy response."},{id:"econ-a2",title:"Data brief",points:25,kind:"Problem set",prompt:"Use a public data source to plot GDP and inflation for one country over ten years and interpret the relationships you find."}]},{slug:"university-data-science",title:"Data Science: From Data to Decisions",subject:"Data Science",branch:"university",level:"Graduate",faculty:"Mathematical, Physical and Life Sciences",code:"D255",teacher:"Dr. Kunle Adeogun",teacherId:"U-104",img:o.data,duration:"10 weeks",lessons:12,blurb:"A graduate-level toolkit for turning messy data into defensible decisions — statistics, machine learning and engineering.",outline:["Statistical thinking","Machine learning foundations","Model evaluation and ethics","Data engineering at scale"],modules:[{id:"ds-m1",title:"Statistical foundations",lessons:[{id:"ds-1",title:"Distributions and uncertainty",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Data is drawn from distributions. We meet the normal and binomial families and quantify uncertainty with standard errors."},{id:"ds-2",title:"Hypothesis testing",minutes:19,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"We formalise how data can falsify hypotheses: null and alternative hypotheses, p-values and the pitfalls of multiple testing."},{id:"ds-3",title:"Regression as a lens",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Linear regression turns relationships into coefficients. We interpret estimates, standard errors and R-squared honestly."}]},{id:"ds-m2",title:"Machine learning",lessons:[{id:"ds-4",title:"The learning problem",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Supervised and unsupervised learning framed as optimisation. We define features, labels, training and test splits up front."},{id:"ds-5",title:"Trees, forests and boosting",minutes:20,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Decision trees are interpretable but unstable. We combine them into ensembles with bagging and boosting for accuracy."},{id:"ds-6",title:"Neural networks",minutes:20,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Activation functions, layers and backpropagation. We build intuition for how networks learn representations without the calculus panic."}]},{id:"ds-m3",title:"Evaluation and engineering",lessons:[{id:"ds-7",title:"Overfitting and generalisation",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Flexible models can memorise noise. We separate training error from test error and use cross-validation to find the sweet spot."},{id:"ds-8",title:"Fairness and transparency",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Models encode values and risks. We audit for bias across subgroups and discuss explainability and accountability."},{id:"ds-9",title:"Pipelines and reproducibility",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Data science is engineering plus insight. We build clean pipelines, version data and models, and make results reproducible."}]}],quiz:{title:"Data Science — Foundations test",questions:[{q:"A p-value below the significance level suggests…",options:["certainty","rejection of the null","no data needed","a larger sample"],answer:1},{q:"Generalisation is about performance on…",options:["training data","unseen data","the mean","labels"],answer:1},{q:"Ensemble methods combine many models to improve…",options:["speed","accuracy","computers","databases"],answer:1},{q:"Standard errors quantify…",options:["certainty","sampling uncertainty","bias only","model size"],answer:1},{q:"The test set should be used…",options:["repeatedly during training","once at evaluation","for labels","during cross-validation"],answer:1}]},assignments:[{id:"ds-a1",title:"Model comparison",points:30,kind:"Problem set",prompt:"Train and compare three models on a public dataset, evaluate with cross-validation and document your feature and evaluation choices."},{id:"ds-a2",title:"Fairness audit",points:25,kind:"Analysis",prompt:"Audit a model for performance differences across groups and propose mitigations, using the framework from this course."}]},{slug:"university-law",title:"Law: Legal Method and the Common Law",subject:"Law",branch:"university",level:"Undergraduate",faculty:"Divisions",code:"M100",teacher:"Prof. Chinelo Achebe",teacherId:"U-105",img:o.law,duration:"9 weeks",lessons:11,blurb:"How law is made, found and argued — the machinery of statutes, precedent and legal reasoning.",outline:["Sources of law","Statutory interpretation","The doctrine of precedent","Legal reasoning and writing"],modules:[{id:"law-m1",title:"Foundations of legal method",lessons:[{id:"law-1",title:"What is law?",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Law is a system of rules backed by institutions. We distinguish law from morality and custom and map the branches of law."},{id:"law-2",title:"Sources of law",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Statutes, precedent, custom and equity supply legal authority. We rank the sources and see how each is found."},{id:"law-3",title:"The court system",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Courts are arranged in a hierarchy that matters for precedent. We trace a case from first instance to final appeal."}]},{id:"law-m2",title:"Reading and using law",lessons:[{id:"law-4",title:"Statutory interpretation",minutes:18,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Words are ambiguous. We apply the literal, golden and mischief rules and the modern purposive approach to a real statute."},{id:"law-5",title:"Aids to interpretation",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Judges turn to intrinsic and extrinsic aids. We use judicial precedent, dictionaries and reports on the statute."},{id:"law-6",title:"Precedent and ratio decidendi",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Only the ratio of a case binds later courts; obiter remarks merely persuade. We extract ratios and distinguish cases."}]},{id:"law-m3",title:"Lawyering: reasoning and writing",lessons:[{id:"law-7",title:"Deductive and analogous reasoning",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Legal argument reasons from rules to facts and from case to case. We rehearse both patterns with short problems."},{id:"law-8",title:"Reading cases critically",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"A judgment is an argument. We dissect facts, issues, holdings and reasoning in a landmark case."},{id:"law-9",title:"Legal writing and citation",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Precision is the currency of law. We draft a short advice and cite authority in standard form."}]}],quiz:{title:"Law — Legal method test",questions:[{q:"The binding part of a case is its…",options:["obiter","ratio decidendi","dissenting judgment","appendix"],answer:1},{q:"The mischief rule focuses on…",options:["the plain meaning","the gap the law aimed to fix","the dictionary","the parties"],answer:1},{q:"Which is a primary source of law?",options:["A textbook","A statute","A law review article","A newspaper"],answer:1},{q:"Courts higher in the hierarchy produce precedent that…",options:["persuades","binds lower courts","is optional","expires"],answer:1},{q:"Guidance in a judgment that is not binding is called…",options:["obiter dicta","ratio","a claim","a writ"],answer:0}]},assignments:[{id:"law-a1",title:"Case brief",points:25,kind:"Analysis",prompt:"Brief a landmark judgment: facts, issues, holding, ratio and one sentence explaining why it is precedent-setting."},{id:"law-a2",title:"Statutory problem",points:25,kind:"Problem set",prompt:"Apply two rules of statutory interpretation to an ambiguous provision and argue which interpretation the court should prefer."}]},{slug:"university-research-methods",title:"Research Methods and Academic Writing",subject:"Research Methods",branch:"university",level:"Graduate",faculty:"Divisions",code:"RMM1",teacher:"Dr. Nadia Yusuf",teacherId:"U-106",img:o.philosophy,duration:"8 weeks",lessons:10,blurb:"Designing research that answers real questions — paradigms, designs, data, ethics and the craft of scholarly writing.",outline:["Research questions and design","Working with sources and evidence","Quantitative and qualitative approaches","Writing and referencing"],modules:[{id:"rm-m1",title:"Designing research",lessons:[{id:"rm-1",title:"The research question",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Research starts with a question worth answering. We refine vague topics into specific, answerable and significant questions."},{id:"rm-2",title:"Research paradigms",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Positivism and interpretivism carry different assumptions about knowledge. We map designs onto their philosophical homes."},{id:"rm-3",title:"Choosing a design",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Experiments, surveys, case studies and archival work each fit different questions. We match designs to research problems."}]},{id:"rm-m2",title:"Working with evidence",lessons:[{id:"rm-4",title:"Literature review",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"A review maps what is known and what is contested. We search systematically, evaluate sources and synthesise themes."},{id:"rm-5",title:"Quantitative methods",minutes:17,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Sampling, measurement and statistical analysis underpin quantitative work. We plan valid measurement and analysis."},{id:"rm-6",title:"Qualitative methods",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Interviews, observation and documents produce rich accounts. We design instruments, collect data and plan analysis."}]},{id:"rm-m3",title:"Writing and ethics",lessons:[{id:"rm-7",title:"Research ethics",minutes:15,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Participants, data and communities carry rights. We cover consent, confidentiality, harm and approval processes."},{id:"rm-8",title:"Academic writing",minutes:16,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Scholarly prose is clear, precise and argued. We draft an abstract, signpost an argument and revise for flow."},{id:"rm-9",title:"Referencing and integrity",minutes:14,video:"https://www.youtube.com/embed/dQw4w9WgXcQ",body:"Citations build the scholarly conversation. We cite and reference consistently and discuss plagiarism and AI use."}]}],quiz:{title:"Research Methods — Foundations test",questions:[{q:"A good research question is…",options:["the broadest possible","specific and answerable","already answered","unanswerable"],answer:1},{q:"Consent, confidentiality and harm concern…",options:["style","ethics","budget","publishing"],answer:1},{q:"A case study is best for…",options:["census data","depth on one phenomenon","wide generalisation","statistics only"],answer:1},{q:"The literature review summarises…",options:["one book","existing scholarship","your results","your CV"],answer:1},{q:"Paradigms in research relate to…",options:["assumptions about knowledge","page margins","software used","grant sizes"],answer:0}]},assignments:[{id:"rm-a1",title:"Research proposal",points:30,kind:"Proposal",prompt:"Draft a one-page proposal: research question, justification, design, methods and ethical considerations."},{id:"rm-a2",title:"Critical source review",points:20,kind:"Analysis",prompt:"Critically evaluate three sources for your topic, judging their credibility, method and contribution."}]}],m=[...g,...b],c=e=>m.find(t=>t.slug===e),v=e=>m.filter(t=>t.branch===e),W=e=>e.bra